              cCtx.fillStyle = '#ef4444'; cCtx.fill(); cCtx.strokeStyle = '#fff'; cCtx.lineWidth = 1; cCtx.stroke();
              cCtx.font = 'bold 5px Inter, system-ui, sans-serif'; cCtx.fillStyle = '#fff'; cCtx.textAlign = 'center';
              cCtx.fillText('O', oiX - 6, oiY - 8.5);
