              cCtx.beginPath(); cCtx.arc(oiX + 6, oiY + 10, 3.5, 0, Math.PI * 2);
              cCtx.fillStyle = '#3b82f6'; cCtx.fill(); cCtx.strokeStyle = '#fff'; cCtx.lineWidth = 1; cCtx.stroke();
              cCtx.fillStyle = '#fff';
