                var boxW = Math.max(htw, fnW) + 14;
                var boxH = briefFn ? 28 : 16;

                var htx = labelOnRight ? pinX + offsetX : pinX - offsetX - boxW;
                var hty = pinY - boxH / 2;
                if (htx < 4) htx = 4;
                if (htx + boxW > W - 4) htx = W - boxW - 4;
                if (hty < 4) hty = 4;
