                cCtx.moveTo(pinX, pinY);
                cCtx.lineTo(labelOnRight ? htx : htx + boxW, hty + boxH / 2);
                cCtx.strokeStyle = sys.accent + '80'; cCtx.lineWidth = 1; cCtx.stroke();

