                // Bottom-left bracket
                cCtx.moveTo(spx - brkR, spy2 + brkR - brkLen); cCtx.lineTo(spx - brkR, spy2 + brkR); cCtx.lineTo(spx - brkR + brkLen, spy2 + brkR);
                // Bottom-right bracket
